import {equipmentIcon} from './equipment-art.js';
import {icon} from './icons.js';
import {EQUIPMENT_TEMPLATES} from './equipment-templates.js';
import {enhancedItemBase} from './equipment-enhancement.js';
import {RARITY,SLOTNAME} from './engine.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isFinite(n)?String(Math.round(n*100)/100):'—';
const enhancementLevel=it=>Number.isInteger(it?.enhancement?.level)?it.enhancement.level:0;
const image=it=>equipmentIcon(it);
const variantLabel=t=>({balanced:'均衡型',attack:'攻击型',defensive:'防护型',armor:'护甲型',vitality:'生命型',element:'元素型',survival:'生存型'})[t.baseVariant?.split('_').at(-1)]??'基础型';
const badge=it=>it.divine?'<small class="divineBadge">神赐</small>':'';
const issueNames={'at-maximum':'已达到试验上限 +5','stale-quote':'装备或费用已变化，请重新预览',max:'已达到试验上限 +5','max-level':'已达到试验上限 +5',gold:'金币不足',funds:'金币不足','insufficient-gold':'金币不足',materials:'所需材料不足',stale:'装备或费用已变化，请重新预览',protected:'当前装备不能改造',pending:'请先完成待确认改造',sandbox:'请进入独立试验'};
export function renderEquipmentWorkshop(s,{templates=EQUIPMENT_TEMPLATES,selectedId=null,selectedTemplate=null,quote=null,lastResult=null,busy=false,error=''}={}){
 const catalog=(Array.isArray(templates)?templates:Object.values(templates??{})).map(t=>({...t,set:t.set??t.setId??null})),plain=catalog.filter(t=>!t.set),sets=catalog.filter(t=>t.set),item=s.inventory?.find(it=>it.id===selectedId),level=enhancementLevel(item),isSandbox=s.developmentEquipmentSandbox===true;
 const validQuote=quote?.ok===true&&quote.itemId===selectedId,canEnhance=!!(item&&isSandbox&&validQuote&&level<5&&!busy&&!lastResult),current=validQuote?quote.bases?.current:item?enhancedItemBase(item,{development:isSandbox}):null,success=validQuote?quote.bases?.success:null,failure=validQuote?quote.bases?.failure:null;
 const selected=catalog.find(t=>t.id===selectedTemplate),issue=error||(!isSandbox?'当前为式样预览；强化需进入独立试验。':quote?.ok===false?(issueNames[quote.reason]??'当前无法强化，请检查装备与试验资源。'):'');
 const cost=validQuote?`${fmt(quote.cost?.gold)} ◈${(quote.cost?.materials??[]).map(m=>' · '+esc(m.name??m.material??m.key??'材料')+' ×'+fmt(m.quantity??m.count)).join('')}`:'—';
 return `<section class="equipmentWorkshop"><div class="workshopTitle">${icon('forge')}<div><span class="eyebrow">EQUIPMENT WORKSHOP</span><h2>装备工坊</h2><small>开发试验 · 不影响正式存档</small></div></div><div class="workshopGrid"><div class="workshopOwned"><h3>选择已有装备 <small>${s.inventory?.length??0}</small></h3><div class="workshopItemGrid">${(s.inventory??[]).map(it=>`<button class="workshopItem r${it.rarity??0} ${it.set?'setFrame':''} ${it.id===selectedId?'selected':''}" data-workshop-item="${esc(it.id)}" ${busy?'disabled':''} aria-pressed="${it.id===selectedId}" title="${esc(it.name)} +${enhancementLevel(it)}">${image(it)}<b>+${enhancementLevel(it)}</b>${it.divine?'<span class="divineDot">✧</span>':''}</button>`).join('')||'<p class="subtleText">没有可选装备。</p>'}</div></div><div class="workshopBench">${item?`<div class="workshopItemHeading"><span class="workshopBigIcon ${item.set?'setFrame':''}">${image(item)}</span><div><h3 class="r${item.rarity??0}text">${esc(item.name)} +${level}${badge(item)}</h3><small>${esc(RARITY[item.rarity]??'装备')} · ${esc(SLOTNAME[item.slot]??item.slot)} · Lv.${fmt(item.level)}</small></div></div><div class="workshopBasePreview"><table><thead><tr><th>基础属性</th><th>原始基底</th><th>当前 +${level}</th><th>成功 +${Math.min(5,level+1)}</th></tr></thead><tbody>${[['atk','攻击'],['armor','护甲'],['hp','生命']].map(([key,label])=>`<tr><th>${label}</th><td>${fmt(item[key])}</td><td>${fmt(current?.[key])}</td><td class="workshopGain">${fmt(success?.[key])}</td></tr>`).join('')}</tbody></table>${validQuote?`<div class="workshopFailurePreview">失败 → +${Math.max(0,level-1)} <span>攻击 ${fmt(failure?.atk)} · 护甲 ${fmt(failure?.armor)} · 生命 ${fmt(failure?.hp)}</span></div>`:''}</div><p class="workshopSmall">普通词条、特殊词条与套装身份不变。这里预览基础数值，不重复叠加神赐。基础增量保留小数，角色面板汇总后取整；微小强化可能暂不改变面板整数。${item.bless?`<br>旧版强化 +${item.bless} 保留，独立计算。`:''}</p><div class="workshopQuote"><div><small>本次费用</small><strong>${cost}</strong></div><div><small>成功机会</small><strong>${validQuote&&Number.isFinite(quote.successRate)?Math.round(quote.successRate*100)+'%':'—'}</strong></div></div><button class="primary workshopEnhance" data-workshop-enhance="${esc(item.id)}" ${canEnhance?'':'disabled'}>${busy?'锻打中…':level>=5?'已达 +5':`尝试强化至 +${level+1}`}</button><p class="workshopSmall">失败仍消耗费用，强化下降1级，最低 +0。当前费用与基础增幅均为试验参数。</p>`:'<div class="workshopEmpty">'+icon('forge')+'<p>从左侧选择一件装备</p></div>'}${lastResult?`<div class="workshopResult ${lastResult.success?'isSuccess':'isFailure'}" role="status"><strong>${lastResult.success?'强化成功':'强化失败'} · +${fmt(lastResult.fromLevel)} → +${fmt(lastResult.toLevel)}</strong><small>本次费用已结算；切换页面不会再次强化。</small><button data-workshop-continue="1" ${busy?'disabled':''}>继续试验</button></div>`:''}${issue?`<p class="workshopError" role="alert">${esc(issue)}</p>`:''}</div></div><details class="workshopCatalog" open><summary>装备式样 <span>${plain.length} 基础 · ${sets.length} 套装</span></summary><p class="workshopSmall">仅查看式样，不赠送装备；实际属性由生成规则决定。</p><div class="workshopTemplateGrid">${catalog.map(t=>`<button class="workshopTemplate ${t.set?'setFrame':''} ${t.id===selectedTemplate?'selected':''}" data-workshop-template="${esc(t.id)}" aria-pressed="${t.id===selectedTemplate}">${image(t)}<span>${esc(t.name)}</span><small>${esc(SLOTNAME[t.slot]??t.slot??'装备')}</small></button>`).join('')}</div>${selected?`<div class="workshopTemplateDetail"><strong>${esc(selected.name)}</strong><span>${esc(SLOTNAME[selected.slot]??selected.slot??'装备')}${selected.set?' · 套装式样':''}${selected.originName?' · '+esc(selected.originName):selected.originRace==='dwarf'?' · 矮人工艺':''}${selected.weaponType?' · '+esc(({axe:'斧',hammer:'锤',sword:'剑',staff:'杖',bow:'弓',dagger:'匕首',mace:'钉锤'})[selected.weaponType]??selected.weaponType):''}</span>${selected.description?'<p>'+esc(selected.description)+'</p>':''}<small>${esc(variantLabel(selected))} · 外观来源：${selected.originRace==='dwarf'?'矮人':esc(selected.originRace??'未标注')}。式样预览，不是已获得物品；数值分配仍待定稿。</small></div>`:''}</details></section>`;
}
